        // Trigger overflow with 1 wei deposit
        vm.startPrank(user);
        depBank.Deposit{value: 1}();
        vm.stopPrank();

        // Verify balance overflowed to zero
        bytes32 postState = vm.load(address(depBank), balanceSlot);
        assertEq(uint256(postState), 0, "Balance should overflow to zero");
    }
}
